//! The `symlink` subcommand: manage the
//! `~/.claude/projects/<encoded-cwd>` symlink that points Claude
//! Code's per-project session directory at this workspace's
//! `.claude` repo.
//!
//! Also home to the shared `SymLink` planner (`new` / `with_meta`
//! / `create`), `encode_path`, and the `install` helper that
//! `vc-x1 init` / `clone` reuse for dual-scope runs.

use std::path::{Path, PathBuf};

use clap::{Args, ValueHint};
use log::{debug, info};

use crate::context::Context;
use crate::subcommand::SubcommandRunner;

/// What action the symlink operation needs to take.
#[derive(Debug, PartialEq, Eq)]
pub enum SymlinkAction {
    /// Nothing exists at the symlink path, create it.
    Create,
    /// An existing symlink points somewhere else, caller must decide whether to replace.
    Replace { current_target: PathBuf },
    /// The symlink already points to the correct target, nothing to do.
    AlreadyCorrect,
}

/// A planned symlink operation.
#[derive(Debug)]
pub struct SymLink {
    /// Absolute path to the target directory (what the symlink points to).
    pub abs_target: PathBuf,
    /// Full path of the symlink to create/replace.
    pub symlink_path: PathBuf,
    /// What action is needed.
    pub action: SymlinkAction,
}

/// Encode a path the way Claude Code does: every character that is
/// not an ASCII letter or digit becomes `-`.
///
/// - Claude Code's rule is `replace(/[^a-zA-Z0-9]/g, "-")`, which
///   runs over UTF-16 code units, so a character outside the Basic
///   Multilingual Plane becomes two dashes.
/// - Not reproduced: Claude Code cuts a name longer than 200
///   characters to 200 and appends a hash of the path.
/// - Source: the installed Claude Code binary, version 2.1.295,
///   read 2026-10-09.
pub fn encode_path(path: &str) -> String {
    let mut name = String::with_capacity(path.len());
    for c in path.chars() {
        if c.is_ascii_alphanumeric() {
            name.push(c);
        } else {
            (0..c.len_utf16()).for_each(|_| name.push('-'));
        }
    }
    name
}

