76	#[derive(Debug)]
77	pub struct DeleteBookmarkParams {
78	    pub repos: Vec<PathBuf>,
79	    pub bookmark: String,
80	    pub skip: Option<Keep>,
81	    pub dry_run: bool,
82	}
