84	impl TryFrom<&DeleteBookmarkArgs> for DeleteBookmarkParams {
85	    type Error = String;
86	
87	    /// Resolve the scope to its repos: `-R` as it is for `-s p`, the
88	    /// pair's sides for `-s w|a|b`.
89	    fn try_from(a: &DeleteBookmarkArgs) -> Result<Self, String> {
90	        let repos = match &a.scope {
91	            RepoScope::Por => match &a.repo {
92	                Some(repo) => vec![repo.clone()],
93	                None => {
94	                    return Err("delete-bookmark -s p: -R is required, the repo to delete \
95	                                the bookmark in"
96	                        .into());
97	                }
98	            },
99	            RepoScope::Sides(sides) => {
100	                let pair = resolve_pair(a.repo.as_deref()).map_err(|e| e.to_string())?;
101	                sides
102	                    .0
103	                    .iter()
104	                    .map(|side| match side {
105	                        Side::Work => pair.work.clone(),
106	                        Side::Bot => pair.agent.clone(),
107	                    })
108	                    .collect()
109	            }
110	        };
111	        Ok(DeleteBookmarkParams {
112	            repos,
113	            bookmark: a.bookmark.clone(),
114	            skip: a.skip,
115	            dry_run: a.dry_run.value,
116	        })
117	    }
118	}
