///
/// - stdout captured (piped): replay at info, since the replay is
///   the captured transcript's only record of the exchange.
/// - stdout a terminal: replay at debug, because the terminal
///   already shows the live line (the stderr prompt plus the
///   user's keystroke echo) and an info replay prints the
///   question twice. The log file still captures debug.
pub fn prompt(msg: &str) -> Result<String, Box<dyn std::error::Error>> {
    use std::io::{IsTerminal, Write};
    eprint!("{msg}");
    std::io::stderr().flush()?;
    let mut response = String::new();
    std::io::stdin().read_line(&mut response)?;
    let trimmed = response.trim().to_string();
    if std::io::stdout().is_terminal() {
        debug!("{msg}{trimmed}");
    } else {
        info!("{msg}{trimmed}");
    }
    Ok(trimmed)
}

/// Whether stdin is a terminal.
///
/// A prompt on a non-tty stdin hangs on `read_line` rather than
/// failing, so a command that is about to ask something tests this
/// first and errors instead. It sits here with [`prompt`], since
/// every prompting command needs it.
pub fn is_stdin_tty() -> bool {
    use std::io::IsTerminal;
    std::io::stdin().is_terminal()
}

/// Lexically normalize a path: collapse `.` / `..` components
/// without touching disk. `std::fs::canonicalize` requires the
/// path to exist, and a destination init or clone is about to create
/// `yes` skips it, which is the default. With the prompt on, a
/// non-tty stdin (`stdin_is_tty`, from the `Context`) is an error
/// rather than a hang, the rule `push`'s step gate follows, and a
/// declined prompt is an error too, so a caller that scripted the
/// run learns it did not happen.
fn confirm(
    params: &SquashPushParams,
    state: &RunState,
    label: &str,
    stdin_is_tty: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    if !params.at_rest {
        debug!("squash-push: push's stage does not ask");
        return Ok(());
    }
    if params.yes {
        debug!("squash-push: --yes skips the prompt");
        return Ok(());
    }
    if !stdin_is_tty {
        return Err(
            "squash-push: asking requires a tty (stdin is not interactive); add --yes to act \
             without asking"
                .into(),
        );
    }
    let answer = crate::common::prompt(&format!("{}. squash-push? [y/N] ", state.line(label)))?;
    let normalized = answer.trim().to_ascii_lowercase();
    if normalized != "y" && normalized != "yes" {
        return Err(format!("squash-push: declined (got {answer:?})").into());
    }
    Ok(())
}

